low.permits_common_action(parent.source, "tool") async def run(): record = await parent.run_async(workflow.context) await parent.build_result(record) return record record = asyncio.run(run()) assert record.units_consumed == 1 and len(choices.calls) == 2 child_id = choices.calls[1]["episode_id"] info, = choices.calls[1]["state"]["scientific_process"]["child_tool_info"] assert set(info) == {"name", "description", "resources", "instructions"} assert info["name"] == operation and info["resources"] == "local" family = "translation" if operation == "sequence.translate" else "extraction" guidance = (PUBLICATION.parents[3] / "gene_annotation_episode/knowledge" / ("sequence-" + family + ".md")).read_text().strip() assert guidance in info["instructions"] returned = json.loads(workflow.journal.row("runtime_forms", child_id)["form"]) row = store.db.execute("SELECT * FROM tool_operations WHERE name=?", (operation,)).fetchone() publication = json.loads(row["result"]) > assert publication["status"] == "completed", publication E AssertionError: {'feedback': {'category': 'partial_execution', 'code': 'representation_error', 'detail': {'field_path': ['measurements...389', 'context_86b6969781ef6ef4a7d488a7', 'feature_97d3c3fa0bdf38fa6f026758', 'product_54f6f8f1bc2dbca7246cc5e4'], ...} E assert 'partial' == 'completed' E E - completed E + partial
